// Test-only loopback renderer. Replays public fixtures generated by the server Rust reducer.
// No Telegram token, login bypass, database, or fixture route enters the production app.
import {createServer} from "vite";
import {readFileSync} from "node:fs";
import {resolve} from "node:path";
import {callRust} from "../packages/runtime/src/index.ts";
const root=resolve(import.meta.dirname,"..");
const side=process.argv.includes("--side0")?0:1;
const port=side===0?5179:5180;
const fixtures=JSON.parse(readFileSync(resolve(root,"apps/web/test/fixtures/online-public-v1.json"),"utf8"));
let phase="loading",version=1,submitted=false,draft=fixtures.loading.own.draft;
const receipts=new Map();
function battle() {
  const b=structuredClone(fixtures[phase]); b.side=side; b.version=version; b.serverNow=Date.now();
  b.loadingDeadline=Date.now()+300000; b.deadline=phase==="active"?Date.now()+30000:null;
  b.own.draft=draft; b.own.submitted=submitted;
  b.players[1].appearance={...b.players[1].appearance,face:"m4",skin:"deep",eyes:"blue",suit:"navy"};
  return b;
}
function account() { const p=battle().players[side]; return {...p,telegram:{...p.telegram,id:100+side},version:1,appearance:{...p.appearance,tag:p.tag},profile:callRust("syncFresh",[])}; }
const server=await createServer({root:resolve(root,"apps/web"),configFile:resolve(root,"apps/web/vite.config.ts"),
  server:{host:"127.0.0.1",port,strictPort:true},plugins:[{name:"online-fixture-only",configureServer(vite){
    vite.middlewares.use(async(req,res,next)=>{
      if(!req.url?.startsWith("/api/online"))return next();
      const path=req.url.slice("/api/online".length);
      let data;
      try{
        if(path==="/me")data={account:account(),maxLevel:4};
        else if(path==="/activity")data={invite:null,battle:phase==="finished"?null:battle()};
        else if(path.endsWith("/commands")){
          const chunks=[];for await(const c of req)chunks.push(c);const body=JSON.parse(Buffer.concat(chunks).toString());
          if(receipts.has(body.commandId))data=receipts.get(body.commandId);
          else{
            const action=body.action;
            if(action.type==="ready"){phase="active";draft=fixtures.active.own.draft;}
            if(action.type==="press")draft=callRust("applyCommand",[battle().match,side,draft,action.command]);
            if(action.type==="submit" || action.type==="surrender"){phase="finished";submitted=false;}
            version++;data={battle:battle()};receipts.set(body.commandId,data);
          }
        } else if(path.startsWith("/matches/"))data={battle:battle()};
        else {res.statusCode=404;data={error:"not_found"};}
      }catch(e){res.statusCode=400;data={error:String(e)};}
      res.setHeader("Content-Type","application/json");res.setHeader("Cache-Control","no-store");res.end(JSON.stringify(data));
    });
  }}]});
await server.listen();
console.log(`Synthetic online render side ${side}: http://127.0.0.1:${port}/?muted=1`);
